private func attachReentrancyListener(
    _ b: ProgramBuilder, to router: Variable, ofGroup group: String
) {
    switch group {
    case "media.mojom.MediaPlayerCallbackRouter":
        attachReentrancyListenerToMediaMojomMediaPlayer(b, router)
    case "blink.mojom.PictureInPictureSessionObserverCallbackRouter":
